def maximum_exam_confusion(answer_key,k):
    def longest(target):
        left=changes=best=0
        for right,char in enumerate(answer_key):
            changes+=char!=target
            while changes>k:
                changes-=answer_key[left]!=target;left+=1
            best=max(best,right-left+1)
        return best
    return max(longest('T'),longest('F'))

